const API="https://ayeza.pythonanywhere.com/todos";function showLoading(){document.getElementById("loadingState").style.display="block",document.getElementById("errorState").style.display="none"}function showError(e){document.getElementById("loadingState").style.display="none",document.getElementById("errorState").style.display="block",document.getElementById("errorMessage").textContent=e}function hideStates(){document.getElementById("loadingState").style.display="none",document.getElementById("errorState").style.display="none"}function renderTodos(e){const t=document.getElementById("todoList");t.innerHTML="",e.forEach(e=>{const o=document.createElement("div");o.className="todo-item",o.innerHTML=`\n      <input type="checkbox" ${e.done?"checked":""} data-id="${e.id}" class="doneCheckbox">\n      <span style="${e.done?"text-decoration:line-through;":""}">${e.title}</span>\n      <button data-id="${e.id}" class="deleteBtn">Delete</button>\n    `,t.appendChild(o)}),document.querySelectorAll(".deleteBtn").forEach(e=>{e.addEventListener("click",()=>deleteTodo(e.dataset.id))}),document.querySelectorAll(".doneCheckbox").forEach(e=>{e.addEventListener("change",()=>toggleDone(e.dataset.id,e.checked))})}async function loadTodos(){showLoading();try{const e=await fetch(API);if(!e.ok)throw new Error(`Server error ${e.status}`);const t=await e.json();hideStates(),renderTodos(t)}catch(e){console.error(e),showError("Couldn't load todos. Is the backend running?")}}async function addTodo(e){try{const t=await fetch(API,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title:e})});if(!t.ok)throw new Error(`Server error ${t.status}`);loadTodos()}catch(e){console.error(e),showError("Couldn't add todo. Try again.")}}async function toggleDone(e,t){try{const o=await fetch(`${API}/${e}`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({done:t})});if(!o.ok)throw new Error(`Server error ${o.status}`);loadTodos()}catch(e){console.error(e),showError("Couldn't update todo.")}}async function deleteTodo(e){try{const t=await fetch(`${API}/${e}`,{method:"DELETE"});if(!t.ok)throw new Error(`Server error ${t.status}`);loadTodos()}catch(e){console.error(e),showError("Couldn't delete todo.")}}document.getElementById("todoForm").addEventListener("submit",function(e){e.preventDefault();const t=document.getElementById("titleInput");t.value.trim()&&(addTodo(t.value.trim()),t.value="")}),document.getElementById("retryButton").addEventListener("click",loadTodos),loadTodos();